<?php
session_start();require_once '../shared/config.php';require_once '../shared/security.php';o2oCsrfToken();requireLogin('customer','login.php');
$db=getDB();$customerId=(int)$_SESSION['customer_id'];$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){o2oRequireCsrf();$type=$_POST['event_type']??'';$allowed=['upcycled'];if(in_array($type,$allowed,true)){ $note=trim($_POST['note']??'');$st=$db->prepare("INSERT INTO eco_events(customer_id,event_type,source_id,reuse_count,note) VALUES(?,?,NULL,1,?)");$st->execute([$customerId,$type,$note?:null]);$message='Your circular-fashion activity was added.';}}
$rent=$db->prepare("SELECT COUNT(*) FROM orders WHERE customer_id=? AND status='completed'");$rent->execute([$customerId]);$rentalCount=(int)$rent->fetchColumn();
$swap=$db->prepare("SELECT COUNT(*) FROM swap_requests sr JOIN swap_listings sl ON sl.id=sr.swap_listing_id WHERE sr.requester_id=? AND sr.status='completed'");$swap->execute([$customerId]);$swapCount=(int)$swap->fetchColumn();
$resale=$db->prepare("SELECT COUNT(*) FROM seller_listings WHERE seller_id=? AND status='sold'");$resale->execute([$customerId]);$resaleCount=(int)$resale->fetchColumn();
$up=$db->prepare("SELECT COUNT(*) FROM eco_events WHERE customer_id=? AND event_type='upcycled'");$up->execute([$customerId]);$upCount=(int)$up->fetchColumn();
$total=$rentalCount+$swapCount+$resaleCount+$upCount;
$events=$db->prepare("SELECT event_type,reuse_count,note,created_at FROM eco_events WHERE customer_id=? ORDER BY created_at DESC LIMIT 10");$events->execute([$customerId]);$events=$events->fetchAll();
